using System.ComponentModel;
using System.Text;
using System.Text.Json;
using ModelContextProtocol.Server;

namespace ApiMcpServer.Tools;

/// <summary>
/// MCP tools that wrap the JSONPlaceholder REST API.
/// Uses constructor injection — IHttpClientFactory and ILogger are resolved by the DI
/// container and never appear in the tool's JSON schema sent to the LLM.
/// </summary>
[McpServerToolType]
public class JsonPlaceholderTools(
    IHttpClientFactory httpClientFactory,
    ILogger<JsonPlaceholderTools> logger)
{
    private static readonly JsonSerializerOptions JsonOptions = new() { WriteIndented = true };

    [McpServerTool, Description("List posts, optionally filtered by user ID.")]
    public async Task<string> ListPosts(
        [Description("Filter posts to this user ID (omit for all posts)")] int? userId = null,
        CancellationToken cancellationToken = default)
    {
        var client = httpClientFactory.CreateClient("api");
        var url = userId.HasValue ? $"/posts?userId={userId}" : "/posts";

        logger.LogInformation("GET {Url}", url);
        var json = await client.GetStringAsync(url, cancellationToken);

        using var doc = JsonDocument.Parse(json);
        var count = doc.RootElement.GetArrayLength();
        return $"Found {count} posts.\n{JsonPrettify(json)}";
    }

    [McpServerTool, Description("Get a single post by its ID.")]
    public async Task<string> GetPost(
        [Description("The post ID (1–100)")] int id,
        CancellationToken cancellationToken = default)
    {
        var client = httpClientFactory.CreateClient("api");

        logger.LogInformation("GET /posts/{Id}", id);
        var response = await client.GetAsync($"/posts/{id}", cancellationToken);
        response.EnsureSuccessStatusCode();

        return JsonPrettify(await response.Content.ReadAsStringAsync(cancellationToken));
    }

    [McpServerTool, Description("Create a new post.")]
    public async Task<string> CreatePost(
        [Description("Title of the post")] string title,
        [Description("Body content of the post")] string body,
        [Description("Author's user ID")] int userId,
        CancellationToken cancellationToken = default)
    {
        var client = httpClientFactory.CreateClient("api");
        var payload = JsonSerializer.Serialize(new { title, body, userId });

        logger.LogInformation("POST /posts");
        var response = await client.PostAsync(
            "/posts",
            new StringContent(payload, Encoding.UTF8, "application/json"),
            cancellationToken);

        response.EnsureSuccessStatusCode();
        return JsonPrettify(await response.Content.ReadAsStringAsync(cancellationToken));
    }

    [McpServerTool, Description("Get all comments for a specific post.")]
    public async Task<string> GetComments(
        [Description("The post ID to get comments for")] int postId,
        CancellationToken cancellationToken = default)
    {
        var client = httpClientFactory.CreateClient("api");

        logger.LogInformation("GET /posts/{PostId}/comments", postId);
        var json = await client.GetStringAsync($"/posts/{postId}/comments", cancellationToken);
        return JsonPrettify(json);
    }

    private static string JsonPrettify(string raw)
    {
        using var doc = JsonDocument.Parse(raw);
        return JsonSerializer.Serialize(doc, JsonOptions);
    }
}

